<?php
namespace Modules\Academy\Services;
use RuntimeException;
class AcademyTermBatchService{
public function seed(int$actor):array{$pdo=db();$courses=$pdo->query("SELECT c.* FROM academy_branch_courses c WHERE c.deleted_at IS NULL ORDER BY c.course_id")->fetchAll();if(!$courses)throw new RuntimeException('ابتدا دوره‌ها را ایجاد کنید.');$currency=(int)($pdo->query('SELECT currency_id FROM financial_system_currency ORDER BY currency_id LIMIT 1')->fetchColumn()?:1);$term=$pdo->prepare("INSERT INTO academy_branch_course_terms(course_id,start_date,end_date,session_count,session_period,price,currency_id,status,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?)");$text=$pdo->prepare("INSERT INTO translations(table_name,table_id,field,locale,value,version,created_by,updated_by) VALUES('academy_branch_course_terms',?,?,?,?,1,?,?)");$booking=$pdo->prepare("INSERT INTO academy_branch_bookings(type,status,requested_date,created_by,updated_by) VALUES('group-class',?,?,?,?)");$session=$pdo->prepare('INSERT INTO academy_branch_course_term_sessions(term_id,booking_id,classroom_id,teacher_id,created_by,updated_by) VALUES(?,?,?,?,?,?)');$enroll=$pdo->prepare("INSERT INTO academy_branch_course_term_enrollments(term_id,member_id,type,status,joined_at,created_by,updated_by) VALUES(?,?,?,'active',NOW(),?,?)");$attendanceStmt=$pdo->prepare('INSERT INTO academy_branch_course_term_session_attendances(session_id,term_enrollment_id,member_id,status,created_by,updated_by) VALUES(?,?,?,?,?,?)');$created=$sessions=$attendance=0;foreach($courses as$index=>$course){$count=1+((int)$course['course_id']%3);$room=(int)($pdo->query('SELECT classroom_id FROM academy_branch_classrooms WHERE branch_id='.(int)$course['branch_id'].' AND deleted_at IS NULL LIMIT 1')->fetchColumn()?:0);if(!$room)continue;$teachers=$this->people((int)$course['branch_id'],'teacher',(int)$course['lesson_id'],max(1,(int)$course['teacher_capacity']));$students=$this->people((int)$course['branch_id'],'student',0,min(3,max(1,(int)$course['student_capacity'])));for($number=1;$number<=$count;$number++){$marker='test-term-c'.(int)$course['course_id'].'-'.$number;if($pdo->query("SELECT 1 FROM translations WHERE table_name='academy_branch_course_terms' AND field='code' AND value=".$pdo->quote($marker).' LIMIT 1')->fetchColumn())continue;$start=date('Y-m-d',strtotime('-'.(($index+$number)%360).' days'));$end=date('Y-m-d',strtotime($start.' +28 days'));$status=strtotime($end)<time()?'finished':'ongoing';$term->execute([(int)$course['course_id'],$start,$end,5,'week',1000000+(($index+$number)%20)*250000,$currency,$status,$actor,$actor]);$termId=(int)$pdo->lastInsertId();foreach(['code'=>$marker,'title'=>'ترم '.$number.' دوره '.(int)$course['course_id'],'summary'=>'ترم آزمایشی دوره شعبه','description'=>'این ترم توسط تست ترم‌ها و حضور و غیاب ایجاد شده است.']as$field=>$value)$text->execute([$termId,$field,'fa',$value,$actor,$actor]);$enrollments=[];foreach(array_merge(array_map(fn($x)=>[$x,'teacher'],$teachers),array_map(fn($x)=>[$x,'student'],$students))as[$member,$type]){$enroll->execute([$termId,$member,$type,$actor,$actor]);$enrollments[]=[(int)$pdo->lastInsertId(),$member];}for($i=0;$i<5;$i++){$date=date('Y-m-d',strtotime($start.' +'.(7*$i).' days'));$held=strtotime($date)<=time();$booking->execute([$held?'completed':'approved',$date,$actor,$actor]);$bookingId=(int)$pdo->lastInsertId();$teacher=$teachers?$teachers[$i%count($teachers)]:null;$session->execute([$termId,$bookingId,$room,$teacher,$actor,$actor]);$sessionId=(int)$pdo->lastInsertId();$sessions++;if($held)foreach($enrollments as[$enrollmentId,$member]){$states=['present','present','present','late','absent'];$attendanceStmt->execute([$sessionId,$enrollmentId,$member,$states[($member+$i)%5],$actor,$actor]);$attendance++;}}$created++;}if(($index+1)%100===0){set_time_limit(120);}}return compact('created','sessions','attendance');}
private function people(int$branch,string$type,int$lesson,int$limit):array{$pdo=db();if($type==='teacher')$sql="SELECT m.member_id FROM academy_branch_members m JOIN academy_branch_member_contracts c ON c.member_id=m.member_id AND c.type='teacher' AND c.deleted_at IS NULL JOIN user_lessons ul ON ul.user_lesson_id=c.user_lesson_id AND ul.lesson_id=$lesson AND ul.deleted_at IS NULL WHERE m.branch_id=$branch AND m.deleted_at IS NULL LIMIT $limit";else$sql="SELECT m.member_id FROM academy_branch_members m LEFT JOIN academy_branch_member_contracts c ON c.member_id=m.member_id AND c.deleted_at IS NULL WHERE m.branch_id=$branch AND m.deleted_at IS NULL AND (c.type='other' OR c.member_contract_id IS NULL) LIMIT $limit";$people=array_map('intval',$pdo->query($sql)->fetchAll(\PDO::FETCH_COLUMN));if(!$people)throw new RuntimeException($type==='teacher'?'برای ساخت ترم آزمایشی، مدرس واجدشرایط این درس در شعبه وجود ندارد.':'برای ساخت ترم آزمایشی، حداقل یک هنرجو در شعبه لازم است.');return$people;}}
